async (page, checks) => {
await page.getByText('Saved on this device').waitFor();
await page.getByLabel('Item to pack').fill('Camera');
await page.getByRole('button', {name: 'Add packing item', exact:true}).click();
await page.getByRole('checkbox', {name:'Camera', exact:true}).check();
await page.reload();
await page.getByRole('checkbox', {name:'Camera', exact:true}).waitFor();
if (!await page.getByRole('checkbox', {name:'Camera', exact:true}).isChecked()) throw Error('Packing state lost');
await page.getByRole('checkbox', {name:'Camera', exact:true}).uncheck();
await page.getByLabel('Item to pack').fill('Charger');
await page.getByRole('button', {name:'Add packing item', exact:true}).click();
await page.getByRole('button', {name:'Remove packing item: Charger', exact:true}).click();
if (await page.locator('.packing-row').count() !== 1) throw Error('Remove failed');
if (!await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth)) throw Error('Page overflow');
}

async (page, checks) => {
await page.emulateMedia({ reducedMotion: 'reduce' });
const item = page.getByRole('checkbox', { name: 'Camera', exact: true });
await item.check();
await item.uncheck();
const transform = await page.locator('.packing-row').evaluate(el => getComputedStyle(el).transform);
if (!checks.isIdentityTransform(transform)) throw Error('Packing row moved');
}
